  public static ScrollState BeginScroll(int n,Rect bounds,ref Vector2 pos){if(!scrollStates.TryGetValue(n,out var state)){state=new ScrollState();scrollStates[n]=state;}nextScrollBoxes[n]=bounds;state.Bounds=bounds;state.Height=bounds.height;if(state.Request>=0){pos.y=state.Request;state.Request=-1;}if(n==wheelTarget&&Wheel!=0)pos.y+=Wheel;float max=Math.Max(0,state.Content-state.Height);if(state.Content>0)pos.y=Math.Clamp(pos.y,0,max);else pos.y=Math.Max(0,pos.y);state.Offset=pos.y;return state;}
