  public static bool Button(Rect r,string label,Transform parent=null){var w=Get("button",NextId(),parent??root,r);bool clicked=w.clicked&&w.label==label;w.clicked=false;w.label=label;w.text.text=label;w.button.interactable=Gui.enabled;return clicked;}
  public static void Label(Rect r,string label,Transform parent=null){var w=Get("label",NextId(),parent??root,r);w.text.text=label;}
  public static string Input(Rect r,string value,Transform parent=null){var w=Get("input",NextId(),parent??root,r);if(w.last!=value&&w.input.text!=value)w.input.SetTextWithoutNotify(value);w.last=value;w.input.interactable=Gui.enabled;return w.input.text;}
  public static void Backdrop(Rect r){var w=Get("backdrop",NextId(),root,r);w.image.sprite=EditorIcons.White;w.image.type=Image.Type.Simple;w.image.color=new Color(0,0,0,.65f);w.image.raycastTarget=false;}
  public static void Box(Rect r,string label){var w=Get("panel",NextId(),root,r);if(label!="")Label(new Rect(r.x+8,r.y+8,r.width-16,r.height-16),label);}
  public static Transform Area(Rect r,Transform parent=null){var w=Get("mask",NextId(),parent??root,r);w.go.SetActive(true);var pos=w.rect.position;var clip=new Rect(pos.x,Screen.height-pos.y,r.width,r.height);if(parent!=null&&clips.TryGetValue(parent.Pointer,out var outer)){float l=Math.Max(clip.x,outer.x),t=Math.Max(clip.y,outer.y),right=Math.Min(clip.xMax,outer.xMax),bottom=Math.Min(clip.yMax,outer.yMax);clip=new Rect(l,t,right-l,bottom-t);}clips[w.go.transform.Pointer]=clip;return w.go.transform;}
 }
 public static class Gui {public static bool enabled=true;public static string tooltip="";public static bool Button(Rect r,string label)=>Renderer.Button(r,label);public static void Label(Rect r,string label)=>Renderer.Label(r,label);public static void Box(Rect r,string label)=>Renderer.Box(r,label);public static void FocusControl(string ignored){if(EventSystem.current!=null)EventSystem.current.SetSelectedGameObject(null);}}
 public static class Layout {
  sealed class Context {public Transform parent;public Rect bounds;public float y,x,startY,maxHeight,viewportHeight;public int scrollId;public Renderer.ScrollState scrollState;public bool horizontal,scroll;public Vector2 offset;public List<(Renderer.Widget,float)> children=new List<(Renderer.Widget,float)>();}
  static readonly Stack<Context> stack=new Stack<Context>();static Context ctx;static float lastFixedWidth;static Rect last;static Vector2 lastGlobal;
  public static void Reset(){stack.Clear();ctx=null;last=new Rect();lastGlobal=Vector2.zero;}
  public static Opt Width(float w)=>new Opt(w);public static Opt Height(float h)=>new Opt(0,h);public static Opt MinWidth(float w)=>new Opt(0);
  public static void BeginArea(Rect r){stack.Push(ctx);ctx=new Context{parent=Renderer.Area(r),bounds=r};}
  public static void EndArea(){ctx=stack.Pop();}
  public static void BeginHorizontal(){stack.Push(ctx);ctx=new Context{parent=ctx.parent,bounds=ctx.bounds,y=ctx.y,startY=ctx.y,horizontal=true,offset=ctx.offset};}
  public static void EndHorizontal(){var child=ctx;float fixedWidth=child.children.Sum(c=>c.Item2>0?c.Item2:0);int flex=child.children.Count(c=>c.Item2<=0);float flexible=flex>0?Math.Max(30,(child.bounds.width-fixedWidth-8*(child.children.Count-1))/flex):0;float x=0;foreach(var item in child.children){float width=item.Item2>0?item.Item2:flexible;Renderer.Move(item.Item1,new Rect(x,child.startY,width,item.Item1.rect.rect.height));x+=width+8;}ctx=stack.Pop();ctx.y=child.startY+Math.Max(38,child.maxHeight)+8;}
  public static Vector2 BeginScrollView(Vector2 pos,params Opt[] options){var previous=ctx;float height=options?.FirstOrDefault(o=>o.height>0)?.height??(ctx.bounds.height-ctx.y-6);var r=new Rect(0,ctx.y,ctx.bounds.width,height);var global=new Rect(ctx.bounds.x,ctx.bounds.y+ctx.y,r.width,r.height);int scrollId=Renderer.NextId();var state=Renderer.BeginScroll(scrollId,global,ref pos);stack.Push(ctx);ctx=new Context{parent=Renderer.Area(r,previous.parent),bounds=new Rect(global.x,global.y,global.width-20,global.height),y=-pos.y,scroll=true,offset=pos,viewportHeight=height,scrollId=scrollId,scrollState=state};return pos;}
  public static void EndScrollView(){var previous=ctx;Renderer.EndScroll(previous.scrollId,previous.scrollState,previous.y+previous.offset.y,previous.parent,previous.bounds.width+20);ctx=stack.Pop();ctx.y+=previous.viewportHeight+8;}
  static Rect Next(float height,Opt[] opts){float width=opts?.FirstOrDefault(o=>o.width>0)?.width??0;lastFixedWidth=width;if(ctx.horizontal){if(width<=0)width=Math.Max(70,ctx.bounds.width-ctx.x);var r=new Rect(ctx.x,ctx.y,width,height);ctx.x+=width+8;ctx.maxHeight=Math.Max(ctx.maxHeight,height);last=new Rect(ctx.bounds.x+r.x,ctx.bounds.y+r.y,r.width,r.height);return r;}else{if(width<=0)width=ctx.bounds.width;var r=new Rect(0,ctx.y,width,height);ctx.y+=height+8;last=new Rect(ctx.bounds.x,ctx.bounds.y+r.y,r.width,r.height);return r;}}
  public static Rect GetLastRect()=>last;
  public static bool IsLastHovered()=>Renderer.LastHovered();
  public static void Label(string text,params Opt[] options){float h=text.Length>48?48:30;Renderer.Label(Next(h,options),text,ctx.parent);Record();}
  public static bool Setting(string title,string value)=>Renderer.Setting(Next(70,null),title,value,ctx.parent);
  public static bool Button(string text,params Opt[] options){bool clicked=Renderer.Button(Next(options?.FirstOrDefault(o=>o.height>0)?.height??40,options),text,ctx.parent);Record();return clicked;}
  public static string TextField(string value,params Opt[] options){string result=Renderer.Input(Next(38,options),value,ctx.parent);Record();return result;}
  public static bool Toggle(bool value,string label,params Opt[] options){if(ctx.horizontal&&(options==null||options.Length==0))options=new[]{Width(65)};bool clicked=Renderer.Button(Next(38,options),(value?"◆ ":"◇ ")+label,ctx.parent);Record();return clicked?!value:value;}
  static void Record(){if(ctx!=null&&ctx.horizontal&&Renderer.LastWidget!=null)ctx.children.Add((Renderer.LastWidget,lastFixedWidth));}
  public static void Space(float size){if(ctx!=null)ctx.y+=size;}
 }
